      "code": "offsets=np.cumsum([0]+[len(obj['triangles']) for obj in geometry['objects']])\nfor label,view,x,y in [('sample_A','TOP',135,175),('sample_B','LEFT',234,483)]:\n frame=buffers[view]; tid=int(frame['triangle_ids'][y,x]); oi=int(np.searchsorted(offsets,tid,side='right')-1); local=tid-int(offsets[oi]); matches=[(i,s) for i,s in enumerate(regions) if s['object_index']==oi and any(a<=local<=b for a,b in s['source_triangle_index_ranges'])]\n print(label,'global/local',tid,local,'object',oi,'matches',matches)\n if matches:\n  i,s=matches[0]; center=np.array(s['center_world_m'],float); u=np.array(s['half_edge_u_world_m'],float); v=np.array(s['half_edge_v_world_m'],float)\n  print('CORNERS',(np.array([center-u-v,center+u-v,center+u+v,center-u+v])).tolist())\nprint('witnesses:')\nfor i,s in enumerate(regions):\n if s['status']!='covered': continue\n p=pixels[s['complete_witness_pixel_index']]; im=imgs[p['image_index']]; frame=buffers[im['image_ref']]\n ids=[int(offsets[s['object_index']])+j for a,b in s['source_triangle_index_ranges'] for j in range(a,b+1)]\n mask=np.isin(frame['triangle_ids'],ids)\n rgb=frame['color'].astype(float); boundary=np.zeros(mask.shape,bool)\n # Different merged surfaces: source-ID differences within this surface excluded.\n for first,second in [((slice(None),slice(None,-1)),(slice(None),slice(1,None))),((slice(None,-1),slice(None)),(slice(1,None),slice(None)))]:\n  contrast=np.linalg.norm(rgb[first]-rgb[second],axis=2)>=24\n  cross=(mask[first]!=mask[second]) & contrast\n  boundary[first] |= cross & mask[first]; boundary[second] |= cross & mask[second]\n count=int(mask.sum()); bc=int(boundary.sum())\n print(i,geometry['objects'][s['object_index']]['name'],s['source_triangle_index_ranges'],im['view_name'],count,bc,'product',p['visible_surface_pixels'],p['contrasting_boundary_pixels'])\nprint('target_C groups',[(obs['unobserved_view_groups']['rows'][g]) for g in regions[11]['unobserved_view_group_indices']])\nprint('target_D groups',[(obs['unobserved_view_groups']['rows'][g]) for g in regions[35]['unobserved_view_group_indices']])\nprint('base source vertices',geometry['objects'][0]['vertices'])\n"
    }
